<?php require_once __DIR__.'/includes/functions.php';$token=(string)($_GET['token']??'');$page_title='ตั้งรหัสผ่านใหม่';require_once __DIR__.'/includes/header.php';?>
<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/auth.css"><div class="auth-page"><section class="auth-shell"><aside class="auth-intro"><p class="eyebrow">NEW PASSWORD</p><h1>ตั้งรหัสผ่านใหม่</h1><p>ใช้รหัสผ่านที่ไม่ซ้ำกับเว็บไซต์อื่น และไม่ควรมีชื่อหรืออีเมลของคุณอยู่ภายใน</p></aside><div class="auth-card"><header class="auth-heading"><h2>สร้างรหัสผ่านใหม่</h2></header><div class="auth-error" id="authError" role="alert"><span></span></div><form class="auth-form" id="resetForm"><div class="auth-field"><label>รหัสผ่านใหม่</label><div class="auth-input"><i class="fa-solid fa-key"></i><input type="password" name="password" minlength="10" maxlength="72" required autocomplete="new-password"></div></div><div class="auth-field"><label>ยืนยันรหัสผ่าน</label><div class="auth-input"><i class="fa-solid fa-key"></i><input type="password" name="password_confirm" minlength="10" maxlength="72" required autocomplete="new-password"></div></div><input type="hidden" name="token" value="<?php echo e($token);?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><button class="btn btn-primary auth-submit">บันทึกรหัสผ่านใหม่</button></form></div></section></div><script>document.getElementById('resetForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),box=document.getElementById('authError');b.disabled=true;try{const r=await fetch(`${BASE_URL}api/password-reset.php`,{method:'POST',body:new FormData(f)}),j=await r.json();if(!r.ok||j.status!=='success')throw new Error(j.message);showToast(j.message,'success');setTimeout(()=>location.href=j.data.redirect,700)}catch(x){box.querySelector('span').textContent=x.message;box.classList.add('show');b.disabled=false}};</script><?php require_once __DIR__.'/includes/footer.php';?>
